css:
.rc-3d-book {
  perspective: 800px;
  width: 60px;
  height: 80px;
  position: relative;
  transform-style: preserve-3d;
  transform: rotateY(-25deg);
  transition: transform 0.6s ease;
}

.rc-3d-gallery {
  perspective: 1000px;
  width: 80px;
  height: 60px;
  position: relative;
  transform-style: preserve-3d;
  animation: roy-3d-gallery-rotate 8s linear infinite;
}

.rc-3d-poster {
  perspective: 1000px;
  width: 80px;
  height: 100px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.1), transparent),
    linear-gradient(135deg, #8b5cf6, #ec4899);
  border-radius: 6px;
  box-shadow:
    0 10px 30px rgba(139, 92, 246, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.1);
  transform: perspective(1000px) rotateY(-15deg) rotateX(5deg);
  transition: transform 0.5s ease;
}

.rc-accordion-3d {
  perspective: 800px;
  width: 80px;
  height: 60px;
  position: relative;
  transform-style: preserve-3d;
}

.rc-apple-bounce-settle {
  animation: roy-apple-bounce-settle 1.2s cubic-bezier(0.28, 0.84, 0.42, 1) both;
}

.rc-apple-elastic-scale {
  animation: roy-apple-elastic 1s cubic-bezier(0.68, -0.55, 0.265, 1.55) both;
}

.rc-apple-flip-spring {
  perspective: 1000px;
  animation: roy-apple-flip-spring 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) both;
  transform-style: preserve-3d;
}

.rc-apple-frosted-vibrancy {
  background: rgba(255, 255, 255, 0.55);
  backdrop-filter: blur(30px) saturate(180%);
  -webkit-backdrop-filter: blur(30px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 14px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 10px 30px rgba(0, 0, 0, 0.15);
  color: #1d1d1f;
}

.rc-apple-material-thick {
  background: rgba(245, 245, 247, 0.75);
  backdrop-filter: blur(40px) saturate(200%);
  -webkit-backdrop-filter: blur(40px) saturate(200%);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 16px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.5) inset,
    0 20px 50px rgba(0, 0, 0, 0.2);
  color: #1d1d1f;
}

.rc-apple-material-thin {
  background: rgba(250, 250, 252, 0.5);
  backdrop-filter: blur(12px) saturate(120%);
  -webkit-backdrop-filter: blur(12px) saturate(120%);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  color: #1d1d1f;
}

.rc-apple-sidebar-material {
  background: linear-gradient(
    180deg,
    rgba(245, 245, 247, 0.7) 0%,
    rgba(235, 235, 240, 0.6) 100%
  );
  backdrop-filter: blur(40px) saturate(150%);
  -webkit-backdrop-filter: blur(40px) saturate(150%);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 12px;
  box-shadow:
    inset 1px 0 0 rgba(255, 255, 255, 0.5),
    0 6px 20px rgba(0, 0, 0, 0.1);
  color: #1d1d1f;
}

.rc-apple-squish-in {
  animation: roy-apple-squish-in 0.7s cubic-bezier(0.32, 0.72, 0, 1) both;
}

.rc-apple-squish-out {
  animation: roy-apple-squish-out 0.55s cubic-bezier(0.32, 0.72, 0, 1) both;
}

.rc-apple-ultra-thin {
  background: rgba(255, 255, 255, 0.4);
  backdrop-filter: blur(8px) saturate(110%);
  -webkit-backdrop-filter: blur(8px) saturate(110%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 10px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.5) inset,
    0 2px 8px rgba(0, 0, 0, 0.06);
  color: #1d1d1f;
}

.rc-apple-vibrancy-dark {
  background: rgba(30, 30, 32, 0.55);
  backdrop-filter: blur(24px) saturate(180%) brightness(0.95);
  -webkit-backdrop-filter: blur(24px) saturate(180%) brightness(0.95);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.08) inset,
    0 10px 30px rgba(0, 0, 0, 0.4);
  color: #f5f5f7;
}

.rc-apple-vibrancy-light {
  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(20px) saturate(180%) brightness(1.05);
  -webkit-backdrop-filter: blur(20px) saturate(180%) brightness(1.05);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 14px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 10px 30px rgba(0, 0, 0, 0.1);
  color: #1d1d1f;
}

.rc-ascii-rain {
  width: 100%;
  min-height: 240px;
  background:
    radial-gradient(ellipse at 50% 0%, #001a0a 0%, #000305 100%);
  position: relative;
  border-radius: 8px;
  overflow: hidden;
}

.rc-bg-animated-gradient {
  background: linear-gradient(-45deg, #065f46, #10b981, #06b6d4, #8b5cf6);
  background-size: 400% 400%;
  animation: roy-gradient-shift 8s ease infinite;
}

.rc-bg-concentric {
  background: repeating-radial-gradient(
    circle at center,
    #10b981 0,
    #10b981 8px,
    #0f172a 8px,
    #0f172a 16px
  );
}

.rc-bg-conic-gradient {
  background: conic-gradient(
    from 0deg at 50% 50%,
    #10b981,
    #06b6d4,
    #8b5cf6,
    #ec4899,
    #f59e0b,
    #10b981
  );
  animation: roy-conic-hue 6s linear infinite;
}

.rc-bg-diagonal-stripes {
  background-color: #0f172a;
  background-image: repeating-linear-gradient(
    -60deg,
    #06b6d4 0,
    #06b6d4 12px,
    #0e7490 12px,
    #0e7490 24px
  );
  background-size: 200% 200%;
  animation: roy-diagonal-shift 6s linear infinite;
}

.rc-bg-dot-pattern {
  background-color: #0f172a;
  background-image: radial-gradient(circle, #10b981 1px, transparent 1px);
  background-size: 24px 24px;
}

.rc-bg-gradient-pulse {
  background-color: #0f172a;
  background-image:
    radial-gradient(circle at 50% 50%, #10b981 0%, rgba(16, 185, 129, 0) 40%),
    radial-gradient(circle at 30% 70%, #06b6d4 0%, rgba(6, 182, 212, 0) 40%),
    radial-gradient(circle at 70% 30%, #8b5cf6 0%, rgba(139, 92, 246, 0) 40%);
  animation: roy-gradient-pulse 4s ease-in-out infinite;
}

.rc-bg-gradient-sweep {
  background: linear-gradient(
    90deg,
    #0f172a 0%,
    #10b981 25%,
    #06b6d4 50%,
    #10b981 75%,
    #0f172a 100%
  );
  background-size: 200% 100%;
  animation: roy-gradient-sweep 4s linear infinite;
}

.rc-bg-grid-lines {
  background-color: #0f172a;
  background-image:
    linear-gradient(rgba(16, 185, 129, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(16, 185, 129, 0.06) 1px, transparent 1px);
  background-size: 48px 48px;
}

.rc-bg-hexagon {
  background-color: #0f172a;
  background-image: url("data:image/svg+xml,%3Csvg width='56' height='100' viewBox='0 0 56 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M28 0L56 16.18V50.5L28 66.68L0 50.5V16.18L28 0z' fill='none' stroke='%2310b981' stroke-width='1' opacity='0.5'/%3E%3Cpath d='M28 33.32L56 49.5V83.82L28 100L0 83.82V49.5L28 33.32z' fill='none' stroke='%2310b981' stroke-width='1' opacity='0.5'/%3E%3C/svg%3E");
  background-size: 56px 100px;
}

.rc-bg-lava-lamp {
  background-color: #1a0b2e;
  position: relative;
  overflow: hidden;
}

.rc-bg-mesh-gradient {
  background-color: #0f172a;
  position: relative;
  overflow: hidden;
}

.rc-bg-noise {
  position: relative;
  background-color: #0f172a;
}

.rc-bg-plaid {
  background-color: #0f172a;
  background-image:
    repeating-linear-gradient(0deg, transparent, transparent 18px, rgba(16, 185, 129, 0.4) 18px, rgba(16, 185, 129, 0.4) 20px),
    repeating-linear-gradient(90deg, transparent, transparent 18px, rgba(16, 185, 129, 0.4) 18px, rgba(16, 185, 129, 0.4) 20px),
    repeating-linear-gradient(45deg, transparent, transparent 24px, rgba(6, 182, 212, 0.3) 24px, rgba(6, 182, 212, 0.3) 26px),
    repeating-linear-gradient(-45deg, transparent, transparent 24px, rgba(6, 182, 212, 0.3) 24px, rgba(6, 182, 212, 0.3) 26px);
}

.rc-bg-radial-rays {
  background-color: #0f172a;
  background-image: repeating-conic-gradient(
    from 0deg at 50% 50%,
    #10b981 0deg 4deg,
    transparent 4deg 12deg
  );
}

.rc-bg-stripes {
  background: repeating-linear-gradient(
    45deg,
    #10b981,
    #10b981 10px,
    #0f172a 10px,
    #0f172a 20px
  );
}

.rc-bg-sunburst {
  background-color: #1a1205;
  position: relative;
  overflow: hidden;
}

.rc-bg-sunset {
  background: linear-gradient(
    180deg,
    #0c1e2e 0%,
    #5b2c6f 25%,
    #c2185b 50%,
    #f59e0b 75%,
    #fde68a 100%
  );
  background-size: 100% 200%;
  animation: roy-sunset-shift 8s ease-in-out infinite;
}

.rc-bg-triangles {
  background-color: #0f172a;
  background-image:
    linear-gradient(45deg, #10b981 25%, transparent 25%),
    linear-gradient(-45deg, #06b6d4 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #06b6d4 75%),
    linear-gradient(-45deg, transparent 75%, #10b981 75%);
  background-size: 40px 40px;
  background-position: 0 0, 0 20px, 20px -20px, -20px 0;
}

.rc-bg-zigzag {
  background-color: #0f172a;
  background-image:
    linear-gradient(135deg, #10b981 25%, transparent 25%) -10px 0,
    linear-gradient(225deg, #10b981 25%, transparent 25%) -10px 0,
    linear-gradient(315deg, #10b981 25%, transparent 25%),
    linear-gradient(45deg, #10b981 25%, transparent 25%);
  background-size: 20px 20px;
}

.rc-blink {
  animation: roy-blink 1.4s steps(2, start) infinite;
}

.rc-blueprint {
  width: 100%;
  min-height: 240px;
  background:
    linear-gradient(0deg,
      transparent 0 calc(100% - 1px), rgba(180,220,255,0.4) calc(100% - 1px) 100%),
    linear-gradient(90deg,
      transparent 0 calc(100% - 1px), rgba(180,220,255,0.4) calc(100% - 1px) 100%),
    repeating-linear-gradient(0deg, transparent 0 19px, rgba(180,220,255,0.18) 19px 20px),
    repeating-linear-gradient(90deg, transparent 0 19px, rgba(180,220,255,0.18) 19px 20px),
    repeating-linear-gradient(0deg, transparent 0 99px, rgba(180,220,255,0.35) 99px 100px),
    repeating-linear-gradient(90deg, transparent 0 99px, rgba(180,220,255,0.35) 99px 100px),
    #0a3d7a;
  background-size: 20px 20px, 20px 20px, 20px 20px, 20px 20px, 100px 100px, 100px 100px, 100% 100%;
  position: relative;
  border-radius: 4px;
  overflow: hidden;
  color: #cfe8ff;
}

.rc-blur-in-up {
  animation: roy-blur-in-up 0.85s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.rc-blur-out-down {
  animation: roy-blur-out-down 0.85s cubic-bezier(0.55, 0, 0.68, 0.53) both;
}

.rc-book-open {
  perspective: 1000px;
  width: 80px;
  height: 60px;
  position: relative;
  transform-style: preserve-3d;
  background: transparent;
}

.rc-border-animated-dash {
  width: 140px;
  height: 80px;
  background: #0f172a;
  border: 3px dashed #10b981;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #d1fae5;
  font-size: 12px;
  font-weight: 600;
  animation: roy-border-dash-glow 1.6s ease-in-out infinite;
}

.rc-border-banner {
  width: 140px;
  height: 80px;
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  clip-path: polygon(0 0, 100% 0, calc(100% - 16px) 50%, 100% 100%, 0 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding-right: 16px;
  box-sizing: border-box;
}

.rc-border-clip-path {
  position: relative;
  width: 140px;
  height: 80px;
  background: linear-gradient(135deg, #10b981, #06b6d4);
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
}

.rc-border-corner-brackets {
  position: relative;
  width: 140px;
  height: 80px;
  background: #0f172a;
  background-image:
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4),
    linear-gradient(#06b6d4, #06b6d4);
  background-position:
    top left, top left,
    top right, top right,
    bottom left, bottom left,
    bottom right, bottom right;
  background-size:
    22px 3px, 3px 22px,
    22px 3px, 3px 22px,
    22px 3px, 3px 22px,
    22px 3px, 3px 22px;
  background-repeat: no-repeat;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #67e8f9;
  font-size: 12px;
  font-weight: 600;
}

.rc-border-dashed-draw {
  position: relative;
  width: 140px;
  height: 80px;
  background: #0f172a;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #a78bfa;
  font-size: 12px;
  font-weight: 600;
}

.rc-border-double-glow {
  position: relative;
  width: 140px;
  height: 80px;
  background: #0f172a;
  border: 1px solid #10b981;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #6ee7b7;
  font-size: 12px;
  font-weight: 600;
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.5), 0 0 24px rgba(16, 185, 129, 0.3), inset 0 0 12px rgba(16, 185, 129, 0.2);
}

.rc-border-frame {
  position: relative;
  width: 140px;
  height: 80px;
  background: #1e293b;
  border: 3px double #f59e0b;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fde68a;
  font-size: 12px;
  font-weight: 600;
  outline: 1px solid #f59e0b;
  outline-offset: 4px;
}

.rc-border-gradient-animated {
  position: relative;
  width: 140px;
  height: 80px;
  background: #0f172a;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
}

.rc-border-inset-glow {
  width: 140px;
  height: 80px;
  background: #0a0a0a;
  border: 1px solid rgba(6, 182, 212, 0.5);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #67e8f9;
  font-size: 12px;
  font-weight: 600;
  box-shadow:
    inset 0 0 22px rgba(6, 182, 212, 0.4),
    inset 0 0 4px rgba(6, 182, 212, 0.7);
}

.rc-border-marching-ants {
  width: 140px;
  height: 80px;
  background-color: #0f172a;
  background-image:
    repeating-linear-gradient(90deg, #f59e0b 0 6px, transparent 6px 12px),
    repeating-linear-gradient(90deg, #f59e0b 0 6px, transparent 6px 12px),
    repeating-linear-gradient(0deg, #f59e0b 0 6px, transparent 6px 12px),
    repeating-linear-gradient(0deg, #f59e0b 0 6px, transparent 6px 12px);
  background-position: 0 0, 0 100%, 0 0, 100% 0;
  background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  background-size: 12px 2px, 12px 2px, 2px 12px, 2px 12px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fde68a;
  font-size: 12px;
  font-weight: 600;
  animation: roy-border-march 0.7s linear infinite;
}

.rc-border-neon-pulse {
  width: 140px;
  height: 80px;
  background: #0a0a0a;
  border: 2px solid #ec4899;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #f9a8d4;
  font-size: 12px;
  font-weight: 600;
  animation: roy-border-neon 1.5s ease-in-out infinite;
}

.rc-border-polaroid {
  width: 140px;
  height: 110px;
  background: #fff;
  padding: 8px 8px 30px;
  box-sizing: border-box;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(-4deg);
}

.rc-border-ribbon {
  width: 140px;
  height: 90px;
  background: #ef4444;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 52% 78%, 0 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding-bottom: 14px;
  box-sizing: border-box;
}

.rc-border-sticker {
  width: 140px;
  height: 80px;
  background: linear-gradient(135deg, #10b981, #06b6d4);
  border: 6px solid #fff;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.3);
  transform: rotate(-3deg);
}

.rc-bounce-in-down {
  animation: roy-bounce-in-down 1s cubic-bezier(0.215, 0.61, 0.355, 1) both;
}

.rc-bounce-in-left {
  animation: roy-bounce-in-left 1s cubic-bezier(0.215, 0.61, 0.355, 1) both;
}

.rc-bounce-in-right {
  animation: roy-bounce-in-right 1s cubic-bezier(0.215, 0.61, 0.355, 1) both;
}

.rc-bounce-in-up {
  animation: roy-bounce-in-up 1s cubic-bezier(0.215, 0.61, 0.355, 1) both;
}

.rc-bounce-out {
  animation: roy-bounce-out 1s ease-in both;
}

.rc-bounce-rotate {
  animation: roy-bounce-rotate 1.1s cubic-bezier(0.28, 1.42, 0.55, 1) both;
}

.rc-breathe {
  animation: roy-breathe 4s ease-in-out infinite;
}

.rc-btn-3d-push {
  position: relative;
  background: #84cc16;
  color: #1a2e05;
  border: none;
  padding: 10px 24px;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 700;
  font-size: 14px;
  box-shadow: 0 5px 0 #65a30d, 0 7px 14px rgba(0, 0, 0, 0.25);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.rc-btn-arrow-slide {
  background: #f97316;
  color: #fff;
  border: none;
  padding: 10px 24px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: gap 0.3s ease, background 0.3s ease;
}

.rc-btn-border-draw {
  position: relative;
  background: transparent;
  color: #10b981;
  border: 2px solid transparent;
  padding: 10px 24px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  z-index: 1;
}

.rc-btn-border-glow {
  background: #1e293b;
  color: #14b8a6;
  border: 2px solid rgba(20, 184, 166, 0.35);
  padding: 10px 24px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.3s ease;
}

.rc-btn-bounce {
  background: #f59e0b;
  color: #fff;
  border: none;
  padding: 10px 24px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
}

.rc-btn-expand {
  background: #10b981;
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0;
  transition: all 0.4s ease;
}

.rc-btn-fill-slide {
  position: relative;
  overflow: hidden;
  z-index: 1;
  background: transparent;
  color: #10b981;
  border: 2px solid #10b981;
  padding: 10px 24px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  transition: color 0.4s ease;
}

.rc-btn-flip {
  background: #ec4899;
  color: #fff;
  border: none;
  padding: 10px 24px;
  border-radius: 12px;
